importScripts('./vendor/lame/lame.min.js');
let encoder;
function pcm16(samples){const out=new Int16Array(samples.length);for(let i=0;i<samples.length;i++){const n=Math.max(-1,Math.min(1,Number.isFinite(samples[i])?samples[i]:0));out[i]=n<0?n*32768:n*32767}return out}
self.onmessage=({data})=>{try{if(data.type==='init'){if(![128,192,256,320].includes(data.bitrate))throw Error('Qualidade MP3 inválida.');encoder=new lamejs.Mp3Encoder(2,data.sampleRate,data.bitrate);self.postMessage({type:'ready'});return}if(!encoder)throw Error('Conversor não preparado.');const pieces=[];if(data.type==='encode'){if(data.left.length!==data.right.length)throw Error('Canais incompatíveis.');const left=pcm16(data.left),right=pcm16(data.right);for(let i=0;i<left.length;i+=1152){const bytes=encoder.encodeBuffer(left.subarray(i,i+1152),right.subarray(i,i+1152));if(bytes.length)pieces.push(new Uint8Array(bytes))}}else if(data.type==='flush'){const bytes=encoder.flush();if(bytes.length)pieces.push(new Uint8Array(bytes));encoder=null}else throw Error('Comando inválido.');const size=pieces.reduce((n,b)=>n+b.length,0),out=new Uint8Array(size);let offset=0;for(const piece of pieces){out.set(piece,offset);offset+=piece.length}self.postMessage({type:data.type==='flush'?'done':'encoded',bytes:out},[out.buffer]);}catch(error){self.postMessage({type:'error',message:error.message||String(error)})}};
